import{_ as a,o as s,c as e,ag as d}from"./chunks/framework.BcZEdlUI.js";const b=JSON.parse('{"title":"安全设计","description":"SceneFab 的安全机制、API 密钥管理和数据保护措施。","frontmatter":{"title":"安全设计","description":"SceneFab 的安全机制、API 密钥管理和数据保护措施。"},"headers":[],"relativePath":"security.md","filePath":"security.md","lastUpdated":1781581339000}'),i={name:"security.md"};function n(r,t,l,h,o,p){return s(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="安全设计" tabindex="-1">安全设计 <a class="header-anchor" href="#安全设计" aria-label="Permalink to &quot;安全设计&quot;">​</a></h1><p>SceneFab 将安全性作为核心设计原则，采用多层防护机制保护用户数据和 API 密钥。</p><hr><h2 id="核心安全原则" tabindex="-1">核心安全原则 <a class="header-anchor" href="#核心安全原则" aria-label="Permalink to &quot;核心安全原则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td><strong>隐私优先</strong></td><td>视频文件永不上传云端，全在本地处理</td></tr><tr><td><strong>最小权限</strong></td><td>仅请求必要的 API 权限</td></tr><tr><td><strong>加密存储</strong></td><td>API Key 使用 OS Keychain 或 Fernet 加密</td></tr><tr><td><strong>零信任</strong></td><td>不假设任何外部服务是可信的</td></tr></tbody></table><hr><h2 id="api-密钥存储" tabindex="-1">API 密钥存储 <a class="header-anchor" href="#api-密钥存储" aria-label="Permalink to &quot;API 密钥存储&quot;">​</a></h2><p>SceneFab 采用多层级密钥存储策略，按优先级依次尝试：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>优先 → OS Keychain（系统级安全存储）</span></span>
<span class="line"><span>        ├── macOS: Keychain Services</span></span>
<span class="line"><span>        ├── Windows: Credential Manager</span></span>
<span class="line"><span>        └── Linux: Secret Service API (GNOME Keyring / KWallet)</span></span>
<span class="line"><span>降级 → 加密文件（Fernet + PBKDF2）</span></span>
<span class="line"><span>        └── ~/.scenefab/credentials.enc</span></span></code></pre></div><h3 id="加密机制" tabindex="-1">加密机制 <a class="header-anchor" href="#加密机制" aria-label="Permalink to &quot;加密机制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>算法</th><th>说明</th></tr></thead><tbody><tr><td>主密钥派生</td><td>PBKDF2</td><td>从用户密码派生 AES 密钥（100,000 次迭代）</td></tr><tr><td>文件加密</td><td>Fernet (AES-128-CBC)</td><td>对称加密存储</td></tr><tr><td>密钥盐值</td><td>随机生成</td><td>每个安装实例独立盐值</td></tr></tbody></table><h3 id="密钥生命周期" tabindex="-1">密钥生命周期 <a class="header-anchor" href="#密钥生命周期" aria-label="Permalink to &quot;密钥生命周期&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成 → 派生 → 加密存储 → 使用 → 轮换 → 销毁</span></span>
<span class="line"><span>  │      │        │        │      │      │</span></span>
<span class="line"><span>  └──────┴────────┴────────┴──────┴──────┘</span></span>
<span class="line"><span>              全程内存加密</span></span></code></pre></div><hr><h2 id="数据隐私" tabindex="-1">数据隐私 <a class="header-anchor" href="#数据隐私" aria-label="Permalink to &quot;数据隐私&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>处理方式</th><th>存储位置</th></tr></thead><tbody><tr><td>视频文件</td><td><strong>永不上传云端</strong>，全在本地处理</td><td>本地磁盘</td></tr><tr><td>解说文字</td><td>仅传输至 AI API（DeepSeek/Qwen），不含视频画面</td><td>内存（临时）</td></tr><tr><td>API Key</td><td>存储于 OS Keychain 或加密文件</td><td>OS Keychain / 加密文件</td></tr><tr><td>配置文件</td><td>本地存储，不上传</td><td><code>~/.scenefab/</code></td></tr><tr><td>日志</td><td>本地存储，脱敏处理</td><td><code>~/.scenefab/logs/</code></td></tr></tbody></table><h3 id="数据传输" tabindex="-1">数据传输 <a class="header-anchor" href="#数据传输" aria-label="Permalink to &quot;数据传输&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本地视频 → [FFmpeg 处理] → 本地输出</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     └─→ 仅文字描述 → [AI API] → 解说稿</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              └─→ 无视频画面传输</span></span></code></pre></div><hr><h2 id="安全最佳实践" tabindex="-1">安全最佳实践 <a class="header-anchor" href="#安全最佳实践" aria-label="Permalink to &quot;安全最佳实践&quot;">​</a></h2><h3 id="密钥管理" tabindex="-1">密钥管理 <a class="header-anchor" href="#密钥管理" aria-label="Permalink to &quot;密钥管理&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">⚠️ 重要</p><ul><li><strong>永远不要</strong>将 API Key 提交到 Git 仓库</li><li><code>.env</code> 文件已加入 <code>.gitignore</code>，请勿移除</li><li>生产环境建议使用 OS Keychain 存储</li><li>定期轮换 API Key（建议每 90 天）</li></ul></div><p>不要把 API Key 写入截图、分享文档、公开仓库或多人可见的项目备注。</p><h3 id="环境隔离" tabindex="-1">环境隔离 <a class="header-anchor" href="#环境隔离" aria-label="Permalink to &quot;环境隔离&quot;">​</a></h3><p>不同账号、不同团队和不同用途建议使用独立 API Key，便于随时吊销和追踪异常调用。</p><h3 id="网络安全" tabindex="-1">网络安全 <a class="header-anchor" href="#网络安全" aria-label="Permalink to &quot;网络安全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>公共网络</td><td>使用 VPN 或代理</td></tr><tr><td>企业网络</td><td>配置 HTTP_PROXY/HTTPS_PROXY</td></tr><tr><td>个人网络</td><td>无需代理时直连即可</td></tr></tbody></table><hr><h2 id="配置路径" tabindex="-1">配置路径 <a class="header-anchor" href="#配置路径" aria-label="Permalink to &quot;配置路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>配置文件目录</th><th>权限建议</th></tr></thead><tbody><tr><td>macOS</td><td><code>~/.scenefab/</code></td><td><code>700</code> (仅用户可访问)</td></tr><tr><td>Windows</td><td><code>C:\\Users\\&lt;user&gt;\\.scenefab\\</code></td><td>仅用户可访问</td></tr><tr><td>Linux</td><td><code>~/.scenefab/</code></td><td><code>700</code> (仅用户可访问)</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设置正确的权限</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 700</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.scenefab/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.scenefab/credentials.enc</span></span></code></pre></div><hr><h2 id="安全审计" tabindex="-1">安全审计 <a class="header-anchor" href="#安全审计" aria-label="Permalink to &quot;安全审计&quot;">​</a></h2><h3 id="日志审计" tabindex="-1">日志审计 <a class="header-anchor" href="#日志审计" aria-label="Permalink to &quot;日志审计&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看 API 调用日志</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.scenefab/logs/api.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;API_CALL&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 检查异常访问</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.scenefab/logs/security.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ALERT&quot;</span></span></code></pre></div><h3 id="定期检查" tabindex="-1">定期检查 <a class="header-anchor" href="#定期检查" aria-label="Permalink to &quot;定期检查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>频率</th><th>说明</th></tr></thead><tbody><tr><td>API Key 轮换</td><td>每 90 天</td><td>在服务商控制台重新生成</td></tr><tr><td>日志审查</td><td>每周</td><td>检查异常调用模式</td></tr><tr><td>应用更新</td><td>每月</td><td>使用最新稳定版本</td></tr><tr><td>安全补丁</td><td>及时</td><td>关注 GitHub Security Advisories</td></tr></tbody></table><hr><h2 id="漏洞报告" tabindex="-1">漏洞报告 <a class="header-anchor" href="#漏洞报告" aria-label="Permalink to &quot;漏洞报告&quot;">​</a></h2><p>如发现安全漏洞，请通过以下方式报告：</p><ul><li><strong>邮箱</strong>：security@agions.com</li><li><strong>GitHub</strong>：<a href="https://github.com/Agions/scene-fab/security/advisories" target="_blank" rel="noreferrer">Security Advisories</a></li></ul><div class="tip custom-block"><p class="custom-block-title">💡 提示</p><p>我们承诺在 48 小时内响应安全漏洞报告。</p></div><hr><h2 id="合规性" tabindex="-1">合规性 <a class="header-anchor" href="#合规性" aria-label="Permalink to &quot;合规性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标准</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>GDPR</td><td>✅ 合规</td><td>不收集个人数据</td></tr><tr><td>CCPA</td><td>✅ 合规</td><td>不出售用户数据</td></tr><tr><td>MIT License</td><td>✅ 开源</td><td>商用和个人使用均无需授权</td></tr></tbody></table>`,45)])])}const k=a(i,[["render",n]]);export{b as __pageData,k as default};
